UPDATE public.practice_questions SET quality_status='remove', quality_reason='mcq_missing_options' WHERE quality_status <> 'remove' AND question_type='mcq' AND (question_data->'options' IS NULL OR COALESCE(question_data->'options'->>'A','')='' OR COALESCE(question_data->'options'->>'B','')='' OR COALESCE(question_data->'options'->>'C','')='' OR COALESCE(question_data->'options'->>'D','')='' OR COALESCE(question_data->'options'->>'E','')='');